const classificacao = $json.choices[0].message.content.trim().toLowerCase();
const agentesValidos = ['historiador', 'conselheiro', 'doutrinador', 'especialista'];
const agente = agentesValidos.includes(classificacao) ? classificacao : 'conselheiro';

return {
  agente,
  user_id: $('Webhook Entrada').item.json.body.user_id,
  message: $('Webhook Entrada').item.json.body.message,
  context_book: $('Webhook Entrada').item.json.body.context_book || null,
  context_chapter: $('Webhook Entrada').item.json.body.context_chapter || null,
  context_verse: $('Webhook Entrada').item.json.body.context_verse || null,
  verse_text: $('Webhook Entrada').item.json.body.verse_text || null
};

const dados = $('Extrair Agente').item.json;
const memorias = $('Buscar Memória RAG').all().map(m => m.json.content).filter(Boolean).join('\n- ');
const perfil = $('Buscar Perfil do Usuário').first().json;

const systemPrompts = {
  historiador: 'Você é O Historiador, agente do Zakar especializado em Antigo Testamento. Sua especialidade: contexto histórico, reis de Israel e Judá, profetas, arqueologia bíblica. Tom: professoral, apaixonado, conta histórias com detalhes vívidos.',
  conselheiro: 'Você é O Conselheiro, agente do Zakar especializado em Livros de Sabedoria. Sua especialidade: Salmos, Provérbios, Eclesiastes, Jó. Aplica o texto bíblico à vida real do usuário com empatia e cuidado.',
  doutrinador: 'Você é O Doutrinador, agente do Zakar especializado em Novo Testamento. Sua especialidade: Evangelhos, Epístolas de Paulo, graça, salvação. Tom: firme, claro, acessível. Explica teologia sem jargão.',
  especialista: 'Você é A Especialista Temática, agente do Zakar. Sua especialidade: temas transversais por toda a Bíblia, biografias bíblicas, tipologia. Tom: entusiasmado, conecta pontos fascinantes entre AT e NT.'
};

const system = systemPrompts[dados.agente] || systemPrompts.conselheiro;
const contextoPerfil = perfil ? `- Nome: ${perfil.name}\n- Momento de vida: ${perfil.life_stage}` : '';
const contextoMemoria = memorias ? `- Fragmentos de memória:\n- ${memorias}` : '- Sem histórico ainda.';
const contextoLeitura = dados.verse_text ? `- Leitura atual: ${dados.context_book} ${dados.context_chapter}:${dados.context_verse}\n- Texto: "${dados.verse_text}"` : '';

const userPrompt = `CONTEXTO DO USUÁRIO:\n${contextoPerfil}\n${contextoMemoria}\n${contextoLeitura}\n\nREGRAS:\n1. Máximo 250 palavras\n2. Nunca invente textos bíblicos\n3. Finalize com uma pergunta ou reflexão\n4. Linguagem acessível\n\nPergunta: ${dados.message}`;

return { agente: dados.agente, user_id: dados.user_id, message: dados.message, system_prompt: system, user_prompt: userPrompt };

const resposta = $json.choices[0].message.content;
const dados = $('Montar Prompt do Agente').item.json;
return { resposta, agente: dados.agente, user_id: dados.user_id, pergunta: dados.message };
